def check_visual_default_breakers(root: Path, findings: Findings) -> None:
    """VF-FIND-032: enforce the visual-default-breaker decision cards / sections.

    - brand-identity.md must reference a Hero Scale decision (DEC-098 or text).
    - brand-identity.md must reference a default Hero Composition Anchor (DEC-099 or text).
    - brand-identity.md must reference a Narrative / concept spine (DEC-100 or text).
    - layout-system.md must contain a "Composition anchor" inventory.
    - layout-system.md must contain a "Cross-section variety" rule.
    - surface-treatments.md must enumerate "Banned" gradient patterns.

    Each missing piece is a WARN. Files that don't exist are not this check's job
    (check_required_files handles existence).
    """
    bi = root / "02-visual-language" / "brand-identity.md"
    ls = root / "03-structure" / "layout-system.md"
    st = root / "02-visual-language" / "surface-treatments.md"

    if bi.exists():
        bi_text = bi.read_text(encoding="utf-8")
        if "Hero Scale" not in bi_text and "Hero scale" not in bi_text:
            findings.warn(
                "VF-FIND-032: brand-identity.md missing Hero Scale decision "
                "(expected DEC-098 or a 'Hero Scale' section). "
                "Hero Scale is required per visual-default-breakers.md §2."
            )
        if "Composition Anchor" not in bi_text and "composition anchor" not in bi_text:
            findings.warn(
                "VF-FIND-032: brand-identity.md missing default Hero Composition Anchor "
                "(expected DEC-099 or a 'Composition Anchor' section). "
                "Required per visual-default-breakers.md §1."
            )
        if "Narrative" not in bi_text and "narrative spine" not in bi_text.lower():
            findings.warn(
                "VF-FIND-032: brand-identity.md missing Narrative / concept spine "
                "(expected DEC-100 or a 'Narrative' section). "
                "Required per visual-default-breakers.md §14."
            )

    if ls.exists():
        ls_text = ls.read_text(encoding="utf-8")
        if "Composition anchor" not in ls_text and "composition-anchor" not in ls_text.lower():
            findings.warn(
                "VF-FIND-032: layout-system.md missing Composition anchor inventory "
                "(expected section listing the 9 anchors). "
                "Required per visual-default-breakers.md §4."
            )
        if "Cross-section variety" not in ls_text and "cross-section" not in ls_text.lower():
            findings.warn(
                "VF-FIND-032: layout-system.md missing Cross-section variety rule. "
                "Required per visual-default-breakers.md §4 and §5."
            )

    if st.exists():
        st_text = st.read_text(encoding="utf-8")
        # Must explicitly enumerate banned gradient patterns (not just mention).
        has_banned_section = (
            "Banned gradient" in st_text
            or "banned gradient" in st_text.lower()
            or "Banned (AI gradient slop)" in st_text
        )
        if not has_banned_section:
            findings.warn(
                "VF-FIND-032: surface-treatments.md does not enumerate banned gradient "
                "patterns. Required per visual-default-breakers.md §6 — must list "
                "purple-to-blue, pink-to-orange, rainbow / mesh blob gradients by name."
            )


