def check_visual_direction_lock_complete(root: Path, findings: Findings) -> None:
    """VF-FIND-035: visual-direction-lock.md must exist and have every required
    commitment filled (no `[...]` placeholders left from the template).

    Existence is enforced by check_required_files (REQUIRED_AUDITABILITY). This
    check verifies completeness — required commitment sections must be present
    AND must not contain unresolved `[...]` placeholder slots.
    """
    p = root / "auditability" / "visual-direction-lock.md"
    if not p.exists():
        return  # existence handled elsewhere
    text = p.read_text(encoding="utf-8")
    required_commitments = [
        "Theme paradigm",
        "Typography character",
        "Hero scale",
        "Hero composition anchor",
        "Narrative",
        "Background mode",
        "Signature components",
        "Motion-implied",
        "Second-read moment",
        "Banned-by-default",
    ]
    missing = [c for c in required_commitments if c.lower() not in text.lower()]
    if missing:
        findings.warn(
            f"VF-FIND-035: visual-direction-lock.md missing commitment sections: "
            f"{missing}. Required per orchestrator Step 0g."
        )
    # Detect unresolved `[...]` placeholders. Tolerate `[ ]` checkboxes (Markdown).
    # Look for the template's literal placeholder shape: `[name + rationale]`,
    # `[name + 1-sentence rationale tied to brand attribute]`, etc.
    placeholder_pattern = re.compile(r"\*\*Chosen:\*\*\s*\[")
    if placeholder_pattern.search(text):
        findings.warn(
            "VF-FIND-035: visual-direction-lock.md contains unresolved `[...]` "
            "placeholders (template values not filled in). Required per orchestrator "
            "quality-gate-before-completion."
        )


