def check_assumption_persona_validation(root: Path, findings: Findings) -> None:
    """VF-FIND-037: any persona file labeled `Source basis: Assumption` or
    `Confidence: Low` must contain a Validation plan section that names a
    research method from the user-research method ladder."""
    personas_dir = root / "01-foundations" / "personas"
    if not personas_dir.exists():
        return
    method_keywords = [
        "interview",
        "usability testing",
        "usability test",
        "survey",
        "card sort",
        "diary",
        "a/b test",
        "analytics cohort",
        "support ticket",
        "support-ticket",
    ]
    # Match markdown-bold variants like `**Source basis:** Assumption`.
    assumption_pattern = re.compile(
        r"Source\s+basis\s*:?\*{0,2}\s*\*{0,2}\s*Assumption", re.IGNORECASE
    )
    low_conf_pattern = re.compile(
        r"Confidence\s*:?\*{0,2}\s*\*{0,2}\s*Low", re.IGNORECASE
    )
    for persona in personas_dir.glob("persona-*.md"):
        text = persona.read_text(encoding="utf-8")
        is_assumption = (
            assumption_pattern.search(text) is not None
            or low_conf_pattern.search(text) is not None
        )
        if not is_assumption:
            continue
        # Find the Validation plan section
        plan_match = re.search(
            r"##\s+Validation plan(.*?)(?=^##\s|\Z)", text, re.MULTILINE | re.DOTALL
        )
        if not plan_match:
            findings.warn(
                f"VF-FIND-037: persona '{persona.name}' is Assumption/Low-confidence "
                f"but has no Validation plan section."
            )
            continue
        plan_text = plan_match.group(1).lower()
        if not any(kw in plan_text for kw in method_keywords):
            findings.warn(
                f"VF-FIND-037: persona '{persona.name}' Validation plan does not name a "
                f"method from the research-method ladder (interview / usability test / "
                f"survey / card sort / diary / A/B / cohort / tickets)."
            )


def check_pressure_test_reviewer_coverage(root: Path, findings: Findings) -> None:
    """VF-FIND-038: design-pressure-test-report.md Pass L must include the new
    Visual-direction critic and React-product-fit critic rows."""
    p = root / "07-quality" / "design-pressure-test-report.md"
    if not p.exists():
        return
    text = p.read_text(encoding="utf-8")
    # Only enforce on reports that include a Pass L section; an earlier-phase report
    # may legitimately not yet have Pass L.
    if "Pass L" not in text and "Multi-expert" not in text:
        return
    missing = []
    if "Visual-direction critic" not in text:
        missing.append("Visual-direction critic")
    if "React-product-fit critic" not in text:
        missing.append("React-product-fit critic")
    if missing:
        findings.warn(
            f"VF-FIND-038: design-pressure-test-report.md Pass L missing reviewer "
            f"rows: {missing}. Required per v1.8.0 — these two lenses catch visual "
            f"defaults and React anti-patterns the existing 6 reviewers miss."
        )


def check_timing_token_drift(root: Path, findings: Findings) -> None:
    """VF-FIND-039: motion-design.md is the source-of-truth for duration / easing
    tokens. micro-interactions.md and scroll-and-gesture.md must not redeclare
    the same token with a different numeric value.
    """
    motion = root / "04-interaction" / "motion-design.md"
    if not motion.exists():
        return
    motion_text = motion.read_text(encoding="utf-8")
    motion_tokens: dict[str, str] = {}
    for m in _TIMING_TOKEN_DECL_PATTERN.finditer(motion_text):
        token, value = m.group(1).lower(), m.group(2)
        motion_tokens.setdefault(token, value)
    if not motion_tokens:
        return

    consumers = [
        ("micro-interactions.md", root / "04-interaction" / "micro-interactions.md"),
        ("scroll-and-gesture.md", root / "04-interaction" / "scroll-and-gesture.md"),
    ]
    for name, path in consumers:
        if not path.exists():
            continue
        text = path.read_text(encoding="utf-8")
        for m in _TIMING_TOKEN_DECL_PATTERN.finditer(text):
            token, value = m.group(1).lower(), m.group(2)
            if token in motion_tokens and motion_tokens[token] != value:
                findings.warn(
                    f"VF-FIND-039: timing-token drift — {name} declares `{token}` as "
                    f"{value}ms but motion-design.md (source of truth) declares it as "
                    f"{motion_tokens[token]}ms. {name} must cite the motion-design "
                    f"value, not redeclare it."
                )
